"""Regenerate the large synthetic fixture modules.

The test runner imports only code-named files, so each fixture is a .ts module exporting its text.

  release-table.ts   a generated release plan: one `### Release n tasks (N)` table per release
  release-groups.ts  its group map, as JSON
  release-steps.ts   release-plan.md (kept beside this script) as a module

Everything is invented and deterministic: run `python3 -I make.py` in this directory and the
three modules come out byte for byte the same.
"""
import json

VERBS = [
    "Add", "Wire", "Cache", "Debounce", "Paginate", "Validate", "Migrate", "Index", "Batch", "Retry",
    "Throttle", "Prefetch", "Label", "Sort", "Filter", "Archive", "Restore", "Share", "Pin", "Snooze",
]
NOUNS = [
    "the inbox list", "the due-date picker", "the reminder sheet", "tag colours", "the sync queue",
    "the offline store", "the search box", "recurring tasks", "the share link", "the undo stack",
    "subtask counts", "the calendar strip", "the settings screen", "push tokens", "the export file",
    "the onboarding card", "list ordering", "the widget refresh", "the login form", "attachment previews",
]
REPOS = ["web", "api", "mobile"]
RELEASES = [  # (release number, rows)
    (0, 60), (1, 110), (2, 190), (3, 30), (4, 2),
]


def cell_date(i):
    return "2026-09-%02d" % (1 + i % 28)


def title(i, extra):
    t = "%s %s" % (VERBS[i % len(VERBS)], NOUNS[(i * 7 + extra) % len(NOUNS)])
    if i % 11 == 0:
        t += " (`item_%d`, both lists)" % i
    if i % 29 == 0:
        t += " with a \\| in the title"
    return t


def rows_for(rel, n):
    rows = []
    for i in range(1, n + 1):
        rows.append(("R%02d-%d" % (rel, i), i))
    if rel == 2:  # carried rows from earlier releases ride in this table
        rows += [("R05-%d" % i, i) for i in range(1, 41)]
        rows += [("R11-%d" % i, i) for i in range(1, 11)]
    return rows


def table():
    out = ["<!-- generated by make.py; regenerate, never edit -->", ""]
    for rel, n in RELEASES:
        rows = rows_for(rel, n)
        out.append("### Release %d tasks (%d)" % (rel, len(rows)))
        out.append("")
        out.append("| task | spec | title | repository | after | items | live | published | landed |")
        out.append("|---|---|---|---|---|---|---|---|---|")
        for k, (tid, i) in enumerate(rows):
            repo = REPOS[k % 3]
            after = "R%02d-%d" % (rel, i - 1) if i > 1 and k % 5 == 0 else "—"
            items = "%d, %d" % (10 + k % 9, 40 + k % 13) if k % 3 else "—"
            live = ("Q%d (release %d, on the staging build)" % (1 + k % 4, rel)) if k % 7 == 0 else ("–" if k % 4 == 0 else "—")
            published = ("%s %07x on train/r%d %s" % (repo, 0x3a5f1c2 + k * 977, rel, cell_date(k))) if k % 5 in (1, 2) else ["—", "-", "–", "[ ]"][k % 4]
            landed = ("%s %07x merged to main %s; build %d" % (repo, 0x91b07e4 + k * 1301, cell_date(k), 100 + k)) if k % 5 == 2 or k % 9 == 0 else ["—", "[ ]", "-"][k % 3]
            if tid == "R02-73":  # a row the flip tests publish themselves
                published = landed = "—"
            out.append("| %s | %02d | %s | %s | %s | %s | %s | %s | %s |" % (
                tid, 1 + k % 12, title(k, rel), repo, after, items, live, published, landed))
        out.append("")
    return "\n".join(out)


def groups():
    g = []

    def add(gid, ttl, rows):
        g.append({"id": gid, "title": ttl, "rows": rows, "lane": "x", "after": []})

    add("UI1", "Settings panel contract and strict lint per screen", ["R05-1", "R05-30"])
    add("UI2", "One list order, everywhere", ["R02-50", "R02-51", "R02-52"])
    add("UI3", "One dark-mode toggle placement and no stale theme in the cache",
        ["R02-73", "R02-41", "R02-40", "UI3/F2", "UI3/F3"])
    add("UI4", "Reminders that survive a restart", ["R02-50", "R02-60", "R02-61"])
    add("UI5", "One tag colour, one digest", ["R02-77"])
    add("API1", "The sync contract and strict types per client leg", ["R05-2", "R05-31"])
    add("API-CORE", "The generic client and streaming as a content producer", ["R05-10", "R05-16"])
    add("API-CORE2", "Retry rules on the generic client and the list, read and tag calls", ["R05-17", "R05-18"])
    add("API12", "One identity per call and capture; the account writer and the share-sheet hook", ["R11-7", "R11-8"])
    n = 6
    for k in range(100, 192, 4):
        add("UI%d" % n, "Screen polish batch %d" % n, ["R02-%d" % j for j in (k, k + 1, k + 2)])
        n += 1
    return json.dumps({"meta": {"date": "2026-10-07", "groups": len(g)}, "groups": g, "held": []}, indent=1, ensure_ascii=False)


def module(name, text, source):
    with open(name + ".ts", "w", encoding="utf-8") as f:
        f.write("// generated by make.py from %s; do not edit\n" % source)
        f.write("export const text: string = " + json.dumps(text, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    module("release-table", table() + "\n", "its own generator")
    module("release-groups", groups() + "\n", "its own generator")
    with open("release-plan.md", encoding="utf-8") as f:
        module("release-steps", f.read(), "release-plan.md")
